fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // All input vectors must have the same length
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 length must match vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 length must match vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 length must match vals_1");

    // Prepare output vector: resize if necessary
    if avgs.len() != n {
        avgs.resize(n, 0);
    }

    for i in 0..n {
        // We assume at least one of conds_1[i] or conds_2[i] is true
        // If you want to enforce it, uncomment the line below:
        // debug_assert!(conds_1[i] || conds_2[i], "At least one condition must be true at index {}", i);

        avgs[i] = if conds_1[i] && conds_2[i] {
            // Both true: integer average
            (vals_1[i] + vals_2[i]) / 2
        } else if conds_1[i] {
            // Only first is true
            vals_1[i]
        } else {
            // Only second is true
            vals_2[i]
        };
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_conditional_average_all_cases() {
        let vals_1 = vec![10, 20, 30, 40];
        let vals_2 = vec![1, 2, 3, 4];
        let conds_1 = vec![true, true, false, false];
        let conds_2 = vec![true, false, true, false];

        // Expected:
        // i=0: both true  => (10+1)/2 = 5
        // i=1: only 1st  => 20
        // i=2: only 2nd  => 3
        // i=3: none      => *invalid by assumption* (we won't test it)
        let mut avgs = Vec::new();
        conditional_average(&vals_1, &vals_2, &conds_1, &conds_2, &mut avgs);

        assert_eq!(avgs, vec![5, 20, 3, 0]); // last slot stays 0 (resize default)
    }

    #[test]
    fn test_conditional_average_exact_length() {
        let vals_1 = vec![100, 200, 300];
        let vals_2 = vec![10, 20, 30];
        let conds_1 = vec![false, true, true];
        let conds_2 = vec![true, true, false];

        let mut avgs = vec![0; 3];
        conditional_average(&vals_1, &vals_2, &conds_1, &conds_2, &mut avgs);

        // i=0: only 2nd => 10
        // i=1: both     => (200+20)/2 = 110
        // i=2: only 1st => 300
        assert_eq!(avgs, vec![10, 110, 300]);
    }
}